import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addWeeks_TriageGen1Test {

    @Test
    public void testAddWeeks_Positive() {
        // Initialize with a known date: 2023-01-01 (Sunday)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);

        // Add 2 weeks
        dt.addWeeks(2);

        // Expected: 2023-01-15
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_Negative() {
        // Initialize with a known date: 2023-01-15
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 0, 0, 0, 0);

        // Subtract 1 week
        dt.addWeeks(-1);

        // Expected: 2023-01-08
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(8, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_Zero() {
        // Initialize with a known date
        MutableDateTime dt = new MutableDateTime(2023, 5, 20, 10, 30, 0, 0);
        long originalMillis = dt.getMillis();

        // Add 0 weeks
        dt.addWeeks(0);

        // Expected: No change
        assertEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAddWeeks_CrossingMonthBoundary() {
        // January 25th, 2023
        MutableDateTime dt = new MutableDateTime(2023, 1, 25, 0, 0, 0, 0);

        // Add 1 week (7 days) -> Feb 1st, 2023
        dt.addWeeks(1);

        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_CrossingYearBoundary() {
        // December 28th, 2023
        MutableDateTime dt = new MutableDateTime(2023, 12, 28, 0, 0, 0, 0);

        // Add 1 week -> January 4th, 2024
        dt.addWeeks(1);

        assertEquals(2024, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(4, dt.getDayOfMonth());
    }

    @Test
    public void testAddWeeks_LeapYear() {
        // Feb 22nd, 2024 (Leap Year)
        MutableDateTime dt = new MutableDateTime(2024, 2, 22, 0, 0, 0, 0);

        // Add 1 week -> Feb 29th, 2024
        dt.addWeeks(1);

        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());

        // Add another week -> March 7th, 2024
        dt.addWeeks(1);
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(7, dt.getDayOfMonth());
    }
}
